      const payload={schemaVersion:'stct-dataset-version-p5.1',datasetId:id,versionId:id,versionNumber:1,parentVersionId:null,kind:'NETWORK_DATA',scope:'DESIGN',source:[{fileName:'Explicit synthetic demo',rawFileHash:hash(network),origin:'EXPLICIT_DEMO',originalBytesStored:false,classification:'SYNTHETIC'}],canonicalDataHash:hash({network,candidateSites:[],costParameters:[]}),mappingHash:hash({kind:'EXPLICIT_DEMO'}),unitContextHash:hash(settings),totalRecords:network.orders.length,acceptedRecords:network.orders.length,rejectedRecords:0,records:{candidateSites:[],costParameters:[]},normalizedScenario:network,conversionLedger:[],settings,validationReport:{status:'READY',totalRecords:network.orders.length,acceptedRecords:network.orders.length,rejectedRecords:0}};
      await repository.commit({records:{datasetVersions:[repository.record(id,payload)]},pointer:{id:`DATASET:${id}`,scope:'DESIGN',type:'DATASET',name:'Explicit synthetic demo',refs:[{store:'datasetVersions',id}]},expectedRevision:0,action:'CREATE_EXPLICIT_DEMO_DATASET'});
